def load_state(sql_text, revision=None):
    try:
        from base_check import parse_sql
    except ImportError:  # direct use outside the tool bundle
        import pathlib
        import sys
        sys.path.insert(0, str(pathlib.Path(__file__).resolve().parents[4] / "tools"))
        from base_check import parse_sql
    rows = [x for x in parse_sql(sql_text) if x["op"] == "insert"]
    ids = set()
    titles = {}                          # seeded tickets' titles come from the SQL itself (r17: ZOM-576 retitled)
    for x in rows:
        r = x["row"]
        if x["table"] == "linear.linear_issues" and r.get("identifier") and r.get("title"):
            titles[str(r["identifier"])] = str(r["title"])
        for c in ("id", "identifier", "document_id", "spreadsheet_id", "contact_id", "event_id"):
            if r.get(c):
                ids.add(str(r[c]))
        if x["table"] == "gmail.gmail_messages" and r.get("thread_id"):
            ids.add(str(r["thread_id"]))
    return {"ids": ids, "titles": titles, "revision": revision or REVISIONS[-1]}


def keys():
    return list(KEYS)


def _off(spec, name, key):
    for d in spec:
        if isinstance(d, tuple):
            if d[0] == name and key in d[1]:
                return True
        elif d == name:
            return True
    return False


def _labels(k):
    return SEEDED_LABELS[k] if k in SEEDED_LABELS else (BASE.get(k) or {}).get("labels", [])


def _has(state, *ids):
    have = state.get("ids") if isinstance(state, dict) else None
    if have is None:
        return True
    return all(i in have for i in ids if not str(i).startswith(("D079SNE2TL4/", "C05433XK267/", "page_", "harmonygames-Games/match3d#")))


def _row(k):
    if k in SEEDED:
        title, call, build = SEEDED[k]
        qa = "reported on the candidates" if k not in ("ZOM-567", "ZOM-569", "ZOM-568", "ART-793", "DES-313") else \
            "still reproduces on the candidates"
        if k == "ZOM-567":
            qa = "server fix held back from prod"
        if k == "ZOM-569":
            qa = "fix landed after the candidate jobs started"
        return {"ticket": k, "title": title, "build status": build, "QA result": qa, "call": call}
    b = BASE[k]
    if k in DONE_CALL:
        call = DONE_CALL[k]
        build = "n/a" if call == "NO CALL" else "in candidate"   # How we gate: no-call tickets are n/a
        qa = "pass on #135 / #50" if k in QA_FIXED_CHECK else "not re-checked"
        if k == "ZOM-435":
            qa = "fails on Android #135"
        if k == "ZOM-473":
            qa = "fails on iOS #50"
        return {"ticket": k, "title": b["title"], "build status": build, "QA result": qa, "call": call}
    call = CALL[k]
    build = "n/a"
    qa = "not re-checked"
    if k in QA_TEXT:
        qa = QA_TEXT[k]
    if k in CANT_REPRO:
        build = "in candidate"   # How we gate: a bug QA saw working on the candidates
    if k == "ZOM-563":
        build, qa = "server - live", "confirmed on prod"
    if k == "ZOM-564":
        build, qa = "in candidate", "pass on #135 / #50"
    return {"ticket": k, "title": b["title"], "build status": build, "QA result": qa, "call": call}


def _group(call):
    return {"BLOCKER": "blocker", "KNOWN ISSUE": "known issue", "FIXED": "fixed", "NO CALL": "no call"}.get(call)


def solve(state, disable=frozenset(), degrade=frozenset(), keys_=None):
    out = {}
    for k in (keys_ or keys()):
        r = _row(k)
        if k in SEEDED and k in ((state.get("titles") or {}) if isinstance(state, dict) else {}):
            r["title"] = state["titles"][k]
        ev = list(DECIDING.get(next(((ru, k) for ru in RULES if (ru, k) in DECIDING), None), []))
        # R_DONE_BUILD: a submission has what was on main when its job started (H1)
        if k == "ZOM-569" and (_off(disable, "R_DONE_BUILD", k) or not _has(state, H1, "cmt_zom569_1")):
            r.update({"call": "FIXED", "build status": "in candidate", "QA result": "not re-checked"})
        # R_DONE_SERVER: merged (even approved, even rolled out) is not live until every server part is on prod
        # (H1; rev1: the withdrawal in #zombie-ops, rev2: Arthur's inline comment that the chest rows are dev-only)
        if k == "ZOM-567" and (_off(disable, "R_DONE_SERVER", k) or
                               not (_has(state, H1) and (_has(state, OPS) or _has(state, INLINE36)))):
            r.update({"call": "FIXED", "build status": "server - live", "QA result": "not re-checked"})
        # R_CORRECTION: the latest re-test on the candidates counts (H2)
        if k == "ZOM-435" and (_off(disable, "R_CORRECTION", k) or not _has(state, TRELLO_435, H2)):
            r.update({"call": "FIXED", "QA result": "pass on #133 / #49"})
        if k == "ZOM-473" and (_off(disable, "R_CORRECTION", k) or not _has(state, DM_473, H2)):
            r.update({"call": "FIXED", "QA result": "not re-checked"})
        # R_ALIAS: the vendor's boss-arena report (old app name) is ZOM-562 and makes it a blocker
        if k == "ZOM-562" and (_off(disable, "R_ALIAS", k) or not _has(state, VENDOR, CONTACT, H2)):
            r.update({"call": "KNOWN ISSUE"})
        # R_COMPLETION: an open ticket whose fix QA confirmed on prod / the candidates is fixed
        if k in ("ZOM-563", "ZOM-564") and (_off(disable, "R_COMPLETION", k) or
                                           (k == "ZOM-564" and not _has(state, "cmt_zom564_1"))):
            r.update({"call": "BLOCKER" if k == "ZOM-564" else "KNOWN ISSUE", "build status": "n/a",
                      "QA result": "not re-checked"})
        # R_SYMPTOM_NOTE: a bare ticket whose reporter later said what goes wrong is called on that (H2)
        if k in SYMPTOM_NOTE:
            cid, call = SYMPTOM_NOTE[k]
            if not _off(disable, "R_SYMPTOM_NOTE", k) and _has(state, cid, H2):
                r.update({"call": call})
        # R_OLD_NOTE: how bad a bug is comes from every check of it, not only its text (H2: "call it on how bad it is")
        if k in OLD_NOTE and not _off(disable, "R_OLD_NOTE", k) and _has(state, BRIAN29, H2):
            r.update({"call": OLD_NOTE[k]})
        # comment-decided calls need their QA comments
        if k in COMMENT_DECIDED and not (k in ("ZOM-564",)):
            cids, fallback = COMMENT_DECIDED[k]
            if not _has(state, *cids):
                r["call"] = fallback
        # R_FILTER: scope is every open ZM ticket in any team, label or state (H2)
        in_scope = True
        if _off(disable, "R_FILTER", k) or not _has(state, H2):
            in_scope = k.startswith("ZOM-") and "Bug" in _labels(k)
        # over-application operators (control members)
        if _off(degrade, "over:every-done-not-in-build", k) and k in ("ZOM-506", "ZOM-557", "ZOM-561"):
            r.update({"call": "KNOWN ISSUE", "build status": "not in candidate"})
        if _off(degrade, "over:every-server-fix-not-live", k) and k == "ZOM-563":
            r.update({"call": "KNOWN ISSUE", "build status": "server - not live"})
        if _off(degrade, "over:every-done-came-back", k) and k in ("ZOM-506", "ZOM-557"):
            r.update({"call": "KNOWN ISSUE", "QA result": "fails on the candidates"})
        if _off(degrade, "over:map-every-refill-report-to-562", k) and k in ("ZOM-504", "ZOM-546"):
            r.update({"call": "BLOCKER"})
        if _off(degrade, "over:every-non-bug-is-defect", k) and k in ("ZOM-565", "ZOM-566", "ART-790"):
            r.update({"call": "KNOWN ISSUE"})
        if _off(degrade, "over:every-in-progress-ships", k) and k in ("ZOM-534", "ZOM-544"):
            r.update({"call": "FIXED"})
        if _off(degrade, "over:every-vague-ticket-is-a-bug", k) and k in ("ZOM-311", "ZOM-130"):
            r.update({"call": "BLOCKER"})
        if _off(degrade, "over:every-cosmetic-is-worse", k) and k in ("ZOM-481", "ZOM-427"):
            r.update({"call": "BLOCKER"})
        # declared channel
        if _off(degrade, "slip:comments", k) and k in COMMENT_DECIDED:
            r["call"] = COMMENT_DECIDED[k][1]
        if not in_scope:
            r = {"ticket": k, "title": "", "build status": "", "QA result": "", "call": ""}
        r["evidence"] = ev
        g = _group(r["call"])
        r["groups"] = (["register", g] if g else [])
        out[k] = r
    return out


def aggregates(rows):
    classes = dict(collections.Counter(v["call"] for v in rows.values() if v.get("call")))
    groups = {}
    for k in sorted(rows):
        for g in rows[k].get("groups") or []:
            groups.setdefault(g, []).append(k)
    return {"classes": classes, "groups": groups}


def evidence(rows, key, field):
    if field in ("ticket", "title"):
        return [key]
    return []


def touched(state, rule):
    if rule == "R_FILTER":
        return {k for k in KEYS if not (k.startswith("ZOM-") and "Bug" in _labels(k))}
    return set(TOUCHED.get(rule, []))


def deciding(state, rule, key):
    if (rule, key) in DECIDING:
        return list(DECIDING[(rule, key)])
    if rule == "R_FILTER":
        return [H2]
    return []


def base_route(record_id):
    if isinstance(record_id, str) and record_id in BASE:
        return {"service": "linear", "file": "data.json", "pointer": "/issues", "field": "identifier"}
    if record_id == "page_qa_runbook":
        return {"service": "confluence", "file": "confluence_working.json", "pointer": "/pages", "field": "id"}
    return None
